<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
const rows=ref<Row[]>([]),scopes=ref<Row[]>([]),editing=ref<Row|null>(null),removing=ref<Row|null>(null),secret=ref(''),error=ref(''),notice=ref(''),busy=ref(false)
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function reload(){const [keys,caps]=await Promise.all([props.api('api-keys'),props.api('api-capabilities')]);rows.value=keys;scopes.value=caps.scopes}
onMounted(()=>void run(reload));onUnmounted(()=>secret.value='')
function create(){editing.value={name:'',scopes:[],expires_at:new Date(Date.now()+90*86400000).toISOString().slice(0,10),rate_limit:120,version:0};preset('read')}
function edit(r:Row){editing.value={...r,scopes:[...r.scopes],expires_at:r.expires_at.slice(0,10)}}
function preset(kind:string){if(!editing.value)return;editing.value.scopes=kind==='read'?['hosts:read','nodes:read','users:read','groups:read','usage:read','subscriptions:read','profiles:read','site:read']:kind==='airport'?['users:read','users:write','groups:read','nodes:read','usage:read','usage:reset','subscriptions:read','subscriptions:write','subscriptions:links']:kind==='telegram'?['users:read','users:write','groups:read','subscriptions:read','subscriptions:write','subscriptions:links','usage:read']:[]}
function save(){const r=editing.value;if(!r)return;void run(async()=>{const result=await props.api('api-keys'+(r.id?'/'+r.id:''),r.id?'PUT':'POST',{name:r.name,scopes:r.scopes,expires_at:new Date(r.expires_at+'T23:59:59').toISOString(),rate_limit:r.rate_limit,version:r.version});editing.value=null;secret.value=result.token||'';notice.value='已保存权限；撤销与权限变更会在后续请求立即检查。';await reload()})}
function revoke(){if(!removing.value)return;const id=removing.value.id;void run(async()=>{await props.api('api-keys/'+id,'DELETE');removing.value=null;await reload()})}
async function copy(){try{await navigator.clipboard.writeText(secret.value);notice.value='已复制 API 密钥'}catch{error.value='请手动选择并复制密钥'}}
</script>
<template><section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">INTEGRATIONS / SCOPED ACCESS</span><h2>API 与外部集成</h2></div><button class="primary" @click="create">创建 API 密钥</button></div><p class="muted">为独立前端、Telegram 机器人等分配所需功能。密钥属于当前自用工作区，权限覆盖此工作区全部资源；尚未提供按主机或按用户隔离。完整管理员令牌不应交给外部应用。</p><p>接口：<code>/api/v1/</code> · <code>Authorization: Bearer xs_…</code> · <code>GET /api/v1/openapi</code></p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><div v-if="secret" class="share-box"><h3>密钥只显示这一次</h3><input :value="secret" readonly aria-label="新 API 密钥" @focus="($event.target as HTMLInputElement).select()"><button class="secondary" @click="copy">复制密钥</button><button class="text-button" @click="secret=''">我已保存，隐藏</button></div><div class="table-scroll"><table><thead><tr><th>名称</th><th>功能权限</th><th>有效期 / 限流</th><th>最近使用</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name}}<small class="block-muted">{{r.revoked_at?'已撤销':new Date(r.expires_at)<new Date()?'已到期':'有效'}}</small></td><td>{{r.scopes.length}} 项<small class="block-muted">{{r.scopes.join(' · ')}}</small></td><td>{{new Date(r.expires_at).toLocaleDateString()}}<small class="block-muted">{{r.rate_limit}} 次 / 分钟</small></td><td>{{r.last_used_at?new Date(r.last_used_at).toLocaleString():'尚未使用'}}</td><td><button class="text-button" :disabled="!!r.revoked_at" @click="edit(r)">修改权限</button><button class="text-button danger" :disabled="!!r.revoked_at" @click="removing=r">撤销</button></td></tr></tbody></table></div><p v-if="!rows.length" class="console-empty">尚未创建外部 API 密钥</p></section>
<div v-if="editing" class="modal-backdrop"><form class="modal" role="dialog" aria-modal="true" aria-label="API 权限配置" @submit.prevent="save"><div class="modal-heading"><h2>{{editing.id?'修改':'创建'}} API 密钥</h2><button class="secondary" type="button" @click="editing=null">关闭</button></div><div class="form-content"><p v-if="error" class="error">{{error}}</p><div class="fields"><label>用途名称<input v-model="editing.name" required maxlength="100" placeholder="独立前端 / Telegram Bot"></label><label>到期日期<input v-model="editing.expires_at" type="date" required></label><label>每分钟请求上限<input v-model.number="editing.rate_limit" type="number" min="1" max="600" required></label></div><h3>权限模板</h3><div class="subnav"><button class="secondary" type="button" @click="preset('read')">只读面板</button><button class="secondary" type="button" @click="preset('telegram')">机器人用户管理</button><button class="secondary" type="button" @click="preset('airport')">机场面板服务端</button><button class="secondary" type="button" @click="preset('custom')">清空，自定义</button></div><div class="choice-list"><label v-for="s in scopes" :key="s.id"><input v-model="editing.scopes" type="checkbox" :value="s.id"><span>{{s.name}}<small class="block-muted">{{s.id}}{{s.sensitive?' · 敏感权限':''}}</small></span></label></div><p class="muted">主机接入、订阅凭据、来源 IP、修改配置分别授权。API 密钥不能创建其他密钥，也不能调用网关特权工作接口。跨域前端还需在站点设置中填写准确的 HTTPS 来源。</p></div><div class="modal-footer"><button class="secondary" type="button" @click="editing=null">取消</button><button class="primary" :disabled="busy||!editing.scopes.length">保存权限</button></div></form></div><div v-if="removing" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="form-content"><h2>撤销 {{removing.name}}？</h2><p>使用此密钥的后续请求会立即失效。此操作不可恢复，需要重新创建密钥。</p><p v-if="error" class="error">{{error}}</p></div><div class="modal-footer"><button class="secondary" @click="removing=null">取消</button><button class="primary" :disabled="busy" @click="revoke">确认撤销</button></div></section></div></template>
